-- ── news_articles ─────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS "news_articles" (
  "id" TEXT,
  "title" TEXT NOT NULL,
  "summary" TEXT,
  "source" TEXT,
  "sentiment" TEXT,
  "category" TEXT,
  "url" TEXT,
  "symbols" TEXT,
  "timestamp" TIMESTAMPTZ DEFAULT now(),
  PRIMARY KEY ("id")
);

-- ── news_sentiment_items ─────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS "news_sentiment_items" (
  "id" TEXT,
  "title" TEXT NOT NULL,
  "summary" TEXT,
  "source" TEXT NOT NULL,
  "source_type" TEXT DEFAULT 'INDIAN',
  "url" TEXT,
  "published_at" TIMESTAMPTZ,
  "fetched_at" TIMESTAMPTZ DEFAULT now(),
  "sentiment" TEXT DEFAULT 'NEUTRAL',
  "sentiment_score" DOUBLE PRECISION DEFAULT 0,
  "impact" TEXT DEFAULT 'LOW',
  "category" TEXT DEFAULT 'GENERAL',
  "symbols_json" TEXT,
  "sector" TEXT,
  "ai_scored" BIGINT DEFAULT 0,
  PRIMARY KEY ("id")
);
CREATE INDEX idx_nsi_published ON news_sentiment_items(published_at DESC);
CREATE INDEX idx_nsi_sentiment ON news_sentiment_items(sentiment);
CREATE INDEX idx_nsi_category  ON news_sentiment_items(category);
CREATE INDEX idx_nsi_fetched   ON news_sentiment_items(fetched_at DESC);
CREATE EXTENSION IF NOT EXISTS pg_trgm;
CREATE INDEX idx_nsi_symbols_json_trgm ON news_sentiment_items USING GIN (symbols_json gin_trgm_ops);
CREATE INDEX idx_nsi_title_trgm        ON news_sentiment_items USING GIN (title gin_trgm_ops);

-- ── nse_stocks ─────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS "nse_stocks" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "symbol" TEXT NOT NULL,
  "name" TEXT NOT NULL,
  "sector" TEXT,
  "industry" TEXT,
  "isin" TEXT,
  "listing_date" TEXT,
  "exchange" TEXT DEFAULT 'NSE',
  "status" TEXT DEFAULT 'ACTIVE',
  "market_cap" DOUBLE PRECISION,
  "pe_ratio" DOUBLE PRECISION,
  "dividend_yield" DOUBLE PRECISION,
  "last_updated" TIMESTAMPTZ DEFAULT now(),
  "mcsymbol" TEXT,
  "tlid" TEXT,
  "tlname" TEXT,
  "is_asm" BIGINT DEFAULT 0,
  "gsm_stage" BIGINT DEFAULT 0,
  "surveillance_updated_at" TEXT,
  "is_nifty50" BIGINT DEFAULT 0,
  "is_nifty100" BIGINT DEFAULT 0,
  "is_nifty200" BIGINT DEFAULT 0,
  "is_midcap150" BIGINT DEFAULT 0,
  "is_smallcap250" BIGINT DEFAULT 0,
  "index_flags_updated_at" TEXT,
  "fno_eligible" BIGINT DEFAULT 0,
  "lot_size" DOUBLE PRECISION,
  "fno_lot_updated_at" TEXT,
  UNIQUE ("symbol")
);
CREATE INDEX idx_nse_symbol ON nse_stocks(symbol);
CREATE INDEX idx_nse_sector ON nse_stocks(sector);
CREATE INDEX idx_nse_industry ON nse_stocks(industry);
CREATE INDEX idx_nse_status ON nse_stocks(status);

-- ── nt_fno_expiry ─────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS "nt_fno_expiry" (
  "symbol" TEXT NOT NULL,
  "exchange" TEXT NOT NULL DEFAULT 'NSE',
  "expiry" TEXT NOT NULL,
  "lot_size" BIGINT,
  PRIMARY KEY ("symbol", "exchange", "expiry")
);

-- ── nt_index_change_oi ─────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS "nt_index_change_oi" (
  "index_name" TEXT NOT NULL,
  "date" TEXT NOT NULL,
  "expiry" TEXT NOT NULL,
  "strike" DOUBLE PRECISION NOT NULL,
  "snap_time" TEXT NOT NULL,
  "index_close" DOUBLE PRECISION,
  "calls_change_oi" DOUBLE PRECISION,
  "calls_change_oi_val" DOUBLE PRECISION,
  "puts_change_oi" DOUBLE PRECISION,
  "puts_change_oi_val" DOUBLE PRECISION,
  "fetched_at" TEXT DEFAULT now(),
  PRIMARY KEY ("index_name", "date", "expiry", "strike")
);
CREATE INDEX idx_nt_chg_oi ON nt_index_change_oi(index_name, date DESC);

-- ── nt_index_oi_eod ─────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS "nt_index_oi_eod" (
  "index_name" TEXT NOT NULL,
  "date" TEXT NOT NULL,
  "expiry" TEXT NOT NULL,
  "strike" DOUBLE PRECISION NOT NULL,
  "snap_time" TEXT NOT NULL,
  "index_close" DOUBLE PRECISION,
  "calls_oi" DOUBLE PRECISION,
  "puts_oi" DOUBLE PRECISION,
  "calls_change_oi" DOUBLE PRECISION,
  "puts_change_oi" DOUBLE PRECISION,
  "calls_volume" DOUBLE PRECISION,
  "puts_volume" DOUBLE PRECISION,
  "calls_oi_value" DOUBLE PRECISION,
  "puts_oi_value" DOUBLE PRECISION,
  "fetched_at" TEXT DEFAULT now(),
  PRIMARY KEY ("index_name", "date", "expiry", "strike")
);
CREATE INDEX idx_nt_oi_eod ON nt_index_oi_eod(index_name, date DESC);

-- ── nt_index_pcr_ts ─────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS "nt_index_pcr_ts" (
  "index_name" TEXT NOT NULL,
  "ts" TEXT NOT NULL,
  "expiry" TEXT NOT NULL,
  "pcr" DOUBLE PRECISION,
  "volume_pcr" DOUBLE PRECISION,
  "change_oi_pcr" DOUBLE PRECISION,
  "index_close" DOUBLE PRECISION,
  "fetched_at" TEXT DEFAULT now(),
  PRIMARY KEY ("index_name", "ts", "expiry")
);
CREATE INDEX idx_nt_pcr_ts ON nt_index_pcr_ts(index_name, ts DESC);

-- ── order_book_snapshots ─────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS "order_book_snapshots" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "symbol" TEXT NOT NULL,
  "timestamp" TIMESTAMPTZ NOT NULL,
  "total_buy_qty" BIGINT,
  "total_sell_qty" BIGINT,
  "bid_ask_spread" DOUBLE PRECISION,
  "vwap" DOUBLE PRECISION,
  "created_at" TIMESTAMPTZ DEFAULT now()
);
CREATE INDEX idx_ob_symbol_time ON order_book_snapshots(symbol, timestamp DESC);

-- ── preopen_snapshot ─────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS "preopen_snapshot" (
  "snapshot_date" TEXT,
  "snapshot_time" TEXT,
  "gift_nifty" DOUBLE PRECISION,
  "gift_nifty_chg" DOUBLE PRECISION,
  "gift_nifty_pct" DOUBLE PRECISION,
  "dj_futures" DOUBLE PRECISION,
  "dj_futures_pct" DOUBLE PRECISION,
  "hang_seng_pct" DOUBLE PRECISION,
  "nikkei_pct" DOUBLE PRECISION,
  "nasdaq_pct" DOUBLE PRECISION,
  "asia_sentiment" DOUBLE PRECISION,
  "global_risk_score" DOUBLE PRECISION,
  "fetched_at" TEXT DEFAULT now(),
  PRIMARY KEY ("snapshot_date")
);

-- ── preopen_stock_snapshot ─────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS "preopen_stock_snapshot" (
  "symbol" TEXT NOT NULL,
  "snapshot_date" TEXT NOT NULL,
  "iep" DOUBLE PRECISION,
  "prev_close" DOUBLE PRECISION,
  "iep_gap_pct" DOUBLE PRECISION,
  "total_buy_qty" DOUBLE PRECISION,
  "total_sell_qty" DOUBLE PRECISION,
  "preopen_imbalance" DOUBLE PRECISION,
  "last_price" DOUBLE PRECISION,
  "fetched_at" TEXT DEFAULT now(),
  PRIMARY KEY ("symbol", "snapshot_date")
);

-- ── proprietary_scores_history ─────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS "proprietary_scores_history" (
  "symbol" TEXT NOT NULL,
  "date" TEXT NOT NULL,
  "source" TEXT NOT NULL,
  "score_type" TEXT NOT NULL,
  "score_value" DOUBLE PRECISION,
  "score_label" TEXT,
  "updated_at" TIMESTAMPTZ DEFAULT now(),
  PRIMARY KEY ("symbol", "date", "source", "score_type")
);

-- ── quant_scores ─────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS "quant_scores" (
  "symbol" TEXT,
  "return_1m" DOUBLE PRECISION,
  "return_3m" DOUBLE PRECISION,
  "return_6m" DOUBLE PRECISION,
  "return_12m" DOUBLE PRECISION,
  "above_sma200" BIGINT,
  "sma200_distance_pct" DOUBLE PRECISION,
  "momentum_score" DOUBLE PRECISION,
  "annualized_vol" DOUBLE PRECISION,
  "sharpe_ratio" DOUBLE PRECISION,
  "max_drawdown_1y" DOUBLE PRECISION,
  "vol_rank" DOUBLE PRECISION,
  "sharpe_rank" DOUBLE PRECISION,
  "trailing_pe" DOUBLE PRECISION,
  "forward_pe" DOUBLE PRECISION,
  "debt_to_equity" DOUBLE PRECISION,
  "return_on_equity" DOUBLE PRECISION,
  "operating_margins" DOUBLE PRECISION,
  "revenue_growth" DOUBLE PRECISION,
  "piotroski_f_score" BIGINT,
  "valuation_score" DOUBLE PRECISION,
  "bullish_screener_count" BIGINT,
  "bearish_screener_count" BIGINT,
  "screener_category_breadth" BIGINT,
  "screener_net_score" DOUBLE PRECISION,
  "confluence_rank" DOUBLE PRECISION,
  "rank_momentum" DOUBLE PRECISION,
  "rank_quality" DOUBLE PRECISION,
  "rank_value" DOUBLE PRECISION,
  "rank_composite" DOUBLE PRECISION,
  "composite_class" TEXT,
  "ohlcv_days" BIGINT,
  "last_computed" TIMESTAMPTZ DEFAULT now(),
  "return_1w" DOUBLE PRECISION,
  "beta_1y" DOUBLE PRECISION,
  "beta_6m" DOUBLE PRECISION,
  "sortino_ratio" DOUBLE PRECISION,
  "var_95" DOUBLE PRECISION,
  "mf_quality_score" DOUBLE PRECISION,
  "mf_momentum_score" DOUBLE PRECISION,
  "mf_value_score" DOUBLE PRECISION,
  "mf_risk_adj_score" DOUBLE PRECISION,
  "mf_macro_score" DOUBLE PRECISION,
  "mf_composite_score" DOUBLE PRECISION,
  PRIMARY KEY ("symbol")
);
CREATE INDEX idx_qs_composite  ON quant_scores(rank_composite DESC);
CREATE INDEX idx_qs_momentum   ON quant_scores(rank_momentum DESC);
CREATE INDEX idx_qs_quality    ON quant_scores(rank_quality DESC);
CREATE INDEX idx_qs_value      ON quant_scores(rank_value DESC);
CREATE INDEX idx_qs_class      ON quant_scores(composite_class);

-- ── recommendation_log ─────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS "recommendation_log" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "symbol" TEXT NOT NULL,
  "rec_type" TEXT NOT NULL,
  "signal_date" TEXT NOT NULL,
  "generated_at" TIMESTAMPTZ NOT NULL,
  "timeframe" TEXT,
  "entry_price" DOUBLE PRECISION,
  "stop_loss" DOUBLE PRECISION,
  "target_1" DOUBLE PRECISION,
  "target_2" DOUBLE PRECISION,
  "target_3" DOUBLE PRECISION,
  "confidence_score" DOUBLE PRECISION,
  "signal_score" BIGINT,
  "nifty_regime" TEXT,
  "sector" TEXT,
  "signals_json" TEXT,
  "screener_score" DOUBLE PRECISION,
  "quant_score" DOUBLE PRECISION,
  "sentiment_score" DOUBLE PRECISION,
  "win_probability" DOUBLE PRECISION,
  "reasoning" TEXT,
  "source" TEXT DEFAULT 'platform',
  "status" TEXT DEFAULT 'ACTIVE',
  "actual_exit_price" DOUBLE PRECISION,
  "actual_return_pct" DOUBLE PRECISION,
  "outcome" TEXT,
  "resolved_at" TIMESTAMPTZ,
  "horizon_days" BIGINT DEFAULT 15
);
CREATE INDEX idx_rec_symbol ON recommendation_log(symbol, signal_date DESC);
CREATE INDEX idx_rec_outcome ON recommendation_log(outcome, signal_date DESC);
CREATE INDEX idx_rec_regime  ON recommendation_log(nifty_regime, signal_date DESC);
CREATE UNIQUE INDEX idx_rec_log_uniq
    ON recommendation_log(symbol, signal_date, timeframe, source);

-- ── rl_episodes ─────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS "rl_episodes" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "date" TEXT NOT NULL,
  "state_key" TEXT NOT NULL,
  "action_taken" TEXT NOT NULL,
  "reward" DOUBLE PRECISION,
  "epsilon" DOUBLE PRECISION,
  "notes" TEXT
);
CREATE INDEX idx_rlepi_date ON rl_episodes(date DESC);

-- ── rl_q_table ─────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS "rl_q_table" (
  "state_key" TEXT NOT NULL,
  "action" TEXT NOT NULL,
  "q_value" DOUBLE PRECISION NOT NULL DEFAULT 0.0,
  "visit_count" BIGINT NOT NULL DEFAULT 0,
  "last_updated" TEXT NOT NULL,
  PRIMARY KEY ("state_key", "action")
);

-- ── screener_appearances ─────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS "screener_appearances" (
  "screener_id" TEXT NOT NULL,
  "source" TEXT NOT NULL,
  "symbol" TEXT NOT NULL,
  "appeared_date" TIMESTAMPTZ NOT NULL,
  "exited_date" TIMESTAMPTZ,
  "return_5d" DOUBLE PRECISION,
  "return_10d" DOUBLE PRECISION,
  "return_20d" DOUBLE PRECISION,
  "return_60d" DOUBLE PRECISION,
  "return_120d" DOUBLE PRECISION,
  "nifty_ret_20d" DOUBLE PRECISION,
  "outcome_20d" TEXT,
  PRIMARY KEY ("screener_id", "symbol", "appeared_date")
);
CREATE INDEX idx_sa_date     ON screener_appearances(appeared_date);
CREATE INDEX idx_sa_screener ON screener_appearances(screener_id);
CREATE INDEX idx_scap_symbol ON screener_appearances(symbol, appeared_date DESC);

-- ── screener_catalog ─────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS "screener_catalog" (
  "screener_id" TEXT NOT NULL,
  "source" TEXT NOT NULL,
  "screener_name" TEXT NOT NULL,
  "category" TEXT NOT NULL,
  "subcategory" TEXT,
  "signal_bias" TEXT NOT NULL,
  "investment_horizon" TEXT,
  "confidence" DOUBLE PRECISION NOT NULL,
  "score_0_100" DOUBLE PRECISION,
  "tier" TEXT,
  "sub_mod" DOUBLE PRECISION,
  "horiz_mult" DOUBLE PRECISION,
  PRIMARY KEY ("screener_id", "source")
);

-- ── screener_history_log ─────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS "screener_history_log" (
  "symbol" TEXT NOT NULL,
  "screener_id" TEXT NOT NULL,
  "entry_date" TEXT NOT NULL,
  "exit_date" TEXT,
  "source" TEXT NOT NULL,
  "updated_at" TIMESTAMPTZ DEFAULT now(),
  PRIMARY KEY ("symbol", "screener_id", "entry_date")
);

-- ── screener_master ─────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS "screener_master" (
  "scan_id" TEXT,
  "name" TEXT NOT NULL,
  "source" TEXT NOT NULL,
  "inferred_sentiment" TEXT,
  "inferred_category" TEXT,
  "inferred_timeframe" TEXT DEFAULT 'long_term',
  "confidence" DOUBLE PRECISION,
  "weight_override" DOUBLE PRECISION,
  "last_updated" TIMESTAMPTZ DEFAULT now(),
  "signal_type_tag" TEXT DEFAULT 'OTHER',
  "created_at" TIMESTAMPTZ,
  "updated_at" TIMESTAMPTZ,
  "subcategory" TEXT,
  "tier" TEXT,
  "category_confidence" DOUBLE PRECISION,
  "classified_by" TEXT,
  "stocks_synced_at" TEXT,
  PRIMARY KEY ("scan_id")
);
CREATE INDEX idx_screener_master_created_at ON screener_master(created_at DESC);

-- ── screener_performance_v2 ─────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS "screener_performance_v2" (
  "screener_id" TEXT,
  "source" TEXT NOT NULL,
  "total_appearances" BIGINT DEFAULT 0,
  "resolved_count" BIGINT DEFAULT 0,
  "wr_5d" DOUBLE PRECISION,
  "wr_10d" DOUBLE PRECISION,
  "wr_20d" DOUBLE PRECISION,
  "wr_60d" DOUBLE PRECISION,
  "wr_120d" DOUBLE PRECISION,
  "avg_ret_5d" DOUBLE PRECISION,
  "avg_ret_10d" DOUBLE PRECISION,
  "avg_ret_20d" DOUBLE PRECISION,
  "avg_ret_60d" DOUBLE PRECISION,
  "avg_ret_120d" DOUBLE PRECISION,
  "alpha_20d" DOUBLE PRECISION,
  "alpha_60d" DOUBLE PRECISION,
  "sharpe_20d" DOUBLE PRECISION,
  "max_drawdown" DOUBLE PRECISION,
  "median_ret_20d" DOUBLE PRECISION,
  "bayesian_score" DOUBLE PRECISION,
  "tier" TEXT,
  "data_source" TEXT,
  "last_computed" TIMESTAMPTZ DEFAULT now(),
  PRIMARY KEY ("screener_id")
);

-- ── screener_reliability ─────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS "screener_reliability" (
  "scan_id" TEXT,
  "screener_name" TEXT NOT NULL,
  "source" TEXT NOT NULL,
  "total_signals" BIGINT DEFAULT 0,
  "wins_1d" BIGINT DEFAULT 0,
  "wins_3d" BIGINT DEFAULT 0,
  "wins_7d" BIGINT DEFAULT 0,
  "wins_14d" BIGINT DEFAULT 0,
  "wins_30d" BIGINT DEFAULT 0,
  "win_rate_1d" DOUBLE PRECISION DEFAULT 0,
  "win_rate_7d" DOUBLE PRECISION DEFAULT 0,
  "win_rate_30d" DOUBLE PRECISION DEFAULT 0,
  "avg_return_7d" DOUBLE PRECISION DEFAULT 0,
  "avg_return_30d" DOUBLE PRECISION DEFAULT 0,
  "max_drawdown" DOUBLE PRECISION DEFAULT 0,
  "avg_holding_days" DOUBLE PRECISION DEFAULT 0,
  "reliability_score" DOUBLE PRECISION DEFAULT 50,
  "last_updated" TIMESTAMPTZ DEFAULT now(),
  "win_rate_5d" DOUBLE PRECISION,
  "win_rate_10d" DOUBLE PRECISION,
  "win_rate_20d" DOUBLE PRECISION,
  "win_rate_60d" DOUBLE PRECISION,
  "win_rate_120d" DOUBLE PRECISION,
  PRIMARY KEY ("scan_id")
);
CREATE INDEX idx_sr_source   ON screener_reliability(source);

-- ── screener_runs ─────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS "screener_runs" (
  "run_id" TEXT,
  "screener_id" TEXT NOT NULL,
  "source" TEXT,
  "run_ts" TIMESTAMPTZ DEFAULT now(),
  "params_json" TEXT,
  "top_n" BIGINT DEFAULT 0,
  "raw_count" BIGINT DEFAULT 0,
  "records_json" TEXT,
  "status" TEXT DEFAULT 'COMPLETED',
  PRIMARY KEY ("run_id")
);
CREATE INDEX idx_sr_screener_id ON screener_runs(screener_id);
CREATE INDEX idx_sr_screener ON screener_runs(screener_id, run_ts DESC);
CREATE INDEX idx_sr_run_id   ON screener_runs(run_id);

-- ── screener_weight_history ─────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS "screener_weight_history" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "snapshot_at" TIMESTAMPTZ DEFAULT now(),
  "optimization_method" TEXT DEFAULT 'differential_evolution',
  "category_weights_json" TEXT,
  "source_weights_json" TEXT,
  "screener_overrides_json" TEXT,
  "baseline_win_rate" DOUBLE PRECISION,
  "optimized_win_rate" DOUBLE PRECISION,
  "improvement_pct" DOUBLE PRECISION,
  "training_samples" BIGINT,
  "notes" TEXT
);

-- ── signal_actions ─────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS "signal_actions" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "signal_id" BIGINT NOT NULL,
  "signal_source" TEXT NOT NULL,
  "symbol" TEXT NOT NULL,
  "user_id" TEXT,
  "action_type" TEXT NOT NULL,
  "executed_at" TIMESTAMPTZ NOT NULL,
  "quantity" BIGINT,
  "entry_price_rec" DOUBLE PRECISION,
  "entry_actual" DOUBLE PRECISION,
  "target_price_rec" DOUBLE PRECISION,
  "exit_price_actual" DOUBLE PRECISION,
  "exit_date" TIMESTAMPTZ,
  "pnl" DOUBLE PRECISION,
  "pnl_pct" DOUBLE PRECISION,
  "notes" TEXT,
  "created_at" TIMESTAMPTZ DEFAULT now(),
  "updated_at" TIMESTAMPTZ DEFAULT now(),
  UNIQUE ("signal_id", "user_id")
);
CREATE INDEX idx_sa_user_id ON signal_actions(user_id);
CREATE INDEX idx_sa_symbol ON signal_actions(symbol);
CREATE INDEX idx_sa_source ON signal_actions(signal_source);
CREATE INDEX idx_sa_executed_at ON signal_actions(executed_at DESC);

-- ── signal_excursions ─────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS "signal_excursions" (
  "symbol" TEXT NOT NULL,
  "signal_date" TEXT NOT NULL,
  "horizon_days" BIGINT NOT NULL,
  "entry_price" DOUBLE PRECISION NOT NULL,
  "mfe_pct" DOUBLE PRECISION,
  "mae_pct" DOUBLE PRECISION,
  "days_to_mfe" BIGINT,
  "days_to_mae" BIGINT,
  "mfe_before_mae" BIGINT,
  "trail_exit_pct" DOUBLE PRECISION,
  "trail_exit_day" BIGINT,
  "horizon_close_pct" DOUBLE PRECISION,
  "computed_at" TIMESTAMPTZ DEFAULT now(),
  "atr_pct" DOUBLE PRECISION,
  "tb_label" BIGINT,
  PRIMARY KEY ("symbol", "signal_date", "horizon_days")
);
CREATE INDEX idx_sexc_date ON signal_excursions(signal_date DESC);
CREATE INDEX idx_sexc_sym  ON signal_excursions(symbol);

-- ── signal_outcomes ─────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS "signal_outcomes" (
  "symbol" TEXT NOT NULL,
  "signal_date" TEXT NOT NULL,
  "horizon_days" BIGINT NOT NULL,
  "entry_price" DOUBLE PRECISION NOT NULL,
  "check_date" TEXT,
  "exit_price" DOUBLE PRECISION,
  "return_pct" DOUBLE PRECISION,
  "outcome" TEXT,
  "signal_score" BIGINT,
  "signals_json" TEXT,
  "computed_at" TIMESTAMPTZ DEFAULT now(),
  "max_return_pct" DOUBLE PRECISION,
  -- label_definition ('terminal_pct2' | 'path_barrier' | 'unknown') / is_suspect were
  -- previously added only at runtime by data_integrity_repair.py's ALTER TABLE ... ADD
  -- COLUMN IF NOT EXISTS -- absent here, a fresh bootstrap or DR restore would silently lose
  -- them even though they already exist on the live table. Schema catch-up, 2026-08.
  "label_definition" TEXT,
  "is_suspect" SMALLINT DEFAULT 0,
  PRIMARY KEY ("symbol", "signal_date", "horizon_days")
);
CREATE INDEX idx_sout_date    ON signal_outcomes(signal_date DESC);
CREATE INDEX idx_sout_outcome ON signal_outcomes(outcome);
CREATE INDEX idx_sout_sym     ON signal_outcomes(symbol);
CREATE INDEX idx_so_label     ON signal_outcomes(label_definition);

-- ── signal_portfolio_correlation ─────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS "signal_portfolio_correlation" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "signal_id" BIGINT NOT NULL,
  "portfolio_symbol" TEXT NOT NULL,
  "signal_symbol" TEXT NOT NULL,
  "weight" DOUBLE PRECISION,
  "correlation_score" DOUBLE PRECISION,
  "co_movement_pct" DOUBLE PRECISION,
  "hedge_potential" BIGINT,
  "momentum_alignment" BIGINT,
  "computed_at" TIMESTAMPTZ DEFAULT now(),
  UNIQUE ("signal_id", "portfolio_symbol")
);
CREATE INDEX idx_spc_portfolio_symbol ON signal_portfolio_correlation(portfolio_symbol);
CREATE INDEX idx_spc_correlation_score ON signal_portfolio_correlation(correlation_score DESC);
CREATE INDEX idx_spc_hedge ON signal_portfolio_correlation(hedge_potential);

-- ── signal_source_weights ─────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS "signal_source_weights" (
  "signal_source" TEXT NOT NULL,
  "regime" TEXT NOT NULL,
  "sector" TEXT DEFAULT 'OTHER',
  "win_rate" DOUBLE PRECISION,
  "avg_return_pct" DOUBLE PRECISION,
  "total_signals" BIGINT DEFAULT 0,
  "total_wins" BIGINT DEFAULT 0,
  "total_losses" BIGINT DEFAULT 0,
  "avg_sharpe_ratio" DOUBLE PRECISION,
  "weight_multiplier" DOUBLE PRECISION DEFAULT 1.0,
  "last_updated" TIMESTAMPTZ DEFAULT now(),
  PRIMARY KEY ("signal_source", "regime", "sector")
);
CREATE INDEX idx_source_weights_win_rate ON signal_source_weights(win_rate DESC);
CREATE INDEX idx_source_weights_sector ON signal_source_weights(sector);

-- ── signal_type_stats ─────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS "signal_type_stats" (
  "signal_type" TEXT NOT NULL,
  "horizon_days" BIGINT NOT NULL,
  "market_regime" TEXT NOT NULL DEFAULT 'ALL',
  "total_occurrences" BIGINT DEFAULT 0,
  "win_count" BIGINT DEFAULT 0,
  "avg_return_pct" DOUBLE PRECISION,
  "median_return_pct" DOUBLE PRECISION,
  "win_rate" DOUBLE PRECISION,
  "last_computed" TIMESTAMPTZ DEFAULT now(),
  PRIMARY KEY ("signal_type", "horizon_days", "market_regime")
);

-- ── signal_type_stats_history ─────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS "signal_type_stats_history" (
  "snapshot_date" TEXT NOT NULL,
  "signal_type" TEXT NOT NULL,
  "horizon_days" BIGINT NOT NULL,
  "market_regime" TEXT NOT NULL DEFAULT 'ALL',
  "total_occurrences" BIGINT DEFAULT 0,
  "win_count" BIGINT DEFAULT 0,
  "avg_return_pct" DOUBLE PRECISION,
  "median_return_pct" DOUBLE PRECISION,
  "win_rate" DOUBLE PRECISION,
  PRIMARY KEY ("snapshot_date", "signal_type", "horizon_days", "market_regime")
);
CREATE INDEX idx_sts_hist_date ON signal_type_stats_history(snapshot_date DESC);

-- ── signal_type_weights ─────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS "signal_type_weights" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "signal_type" TEXT NOT NULL,
  "regime" TEXT NOT NULL,
  "sector" TEXT NOT NULL DEFAULT 'ALL',
  "weight" DOUBLE PRECISION NOT NULL DEFAULT 1.0,
  "sample_count" BIGINT NOT NULL DEFAULT 0,
  "last_updated" TEXT NOT NULL,
  UNIQUE ("signal_type", "regime", "sector")
);
CREATE INDEX idx_stw_key ON signal_type_weights(signal_type, regime, sector);

-- ── signal_type_weights_history ─────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS "signal_type_weights_history" (
  "snapshot_date" TEXT NOT NULL,
  "signal_type" TEXT NOT NULL,
  "regime" TEXT NOT NULL,
  "sector" TEXT NOT NULL DEFAULT 'ALL',
  "weight" DOUBLE PRECISION NOT NULL DEFAULT 1.0,
  "sample_count" BIGINT NOT NULL DEFAULT 0,
  PRIMARY KEY ("snapshot_date", "signal_type", "regime", "sector")
);
CREATE INDEX idx_stw_hist_date ON signal_type_weights_history(snapshot_date DESC);

-- ── so_option_chain ─────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS "so_option_chain" (
  "symbol" TEXT NOT NULL,
