CREATE INDEX idx_seb_quarter ON stock_earnings_beats(quarter_date);

-- ── stock_earnings_dates ─────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS "stock_earnings_dates" (
  "scid" TEXT NOT NULL,
  "result_date" TEXT NOT NULL,
  "stock_name" TEXT,
  "result_type" TEXT,
  "result_time" TEXT,
