);
CREATE UNIQUE INDEX idx_sfb_uniq
    ON stock_factor_breakdown(symbol, timeframe);

-- ── stock_fundamentals ─────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS "stock_fundamentals" (
