-- ── strategy_performance ─────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS "strategy_performance" (
  "perf_key" TEXT NOT NULL,
  "strategy_name" TEXT NOT NULL,
  "segment" TEXT NOT NULL,
  "segment_value" TEXT NOT NULL,
  "horizon_days" BIGINT NOT NULL,
  "market_regime" TEXT NOT NULL DEFAULT 'ALL',
  "total_signals" BIGINT DEFAULT 0,
  "win_count" BIGINT DEFAULT 0,
  "loss_count" BIGINT DEFAULT 0,
  "neutral_count" BIGINT DEFAULT 0,
  "win_rate" DOUBLE PRECISION,
  "avg_return_pct" DOUBLE PRECISION,
  "median_return_pct" DOUBLE PRECISION,
  "avg_win_pct" DOUBLE PRECISION,
  "avg_loss_pct" DOUBLE PRECISION,
  "profit_factor" DOUBLE PRECISION,
  "sharpe_ratio" DOUBLE PRECISION,
  "max_drawdown_pct" DOUBLE PRECISION,
