  "worst_sector" TEXT,
  "last_computed" TIMESTAMPTZ DEFAULT now(),
  PRIMARY KEY ("perf_key", "horizon_days", "market_regime")
);
CREATE INDEX idx_perfkey ON strategy_performance(strategy_name, horizon_days);

