-- ── tick_data ─────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS "tick_data" (
  "symbol" TEXT NOT NULL,
  "tick_time" TIMESTAMPTZ NOT NULL,
  "price" DOUBLE PRECISION NOT NULL,
  "bid" DOUBLE PRECISION,
  "ask" DOUBLE PRECISION,
  "volume" BIGINT,
  "volume_cum" BIGINT,
