);
CREATE INDEX idx_tick_symbol ON tick_data(symbol, tick_time DESC);
CREATE INDEX idx_tick_date ON tick_data(tick_time DESC);

-- ── timeframe_scores ─────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS "timeframe_scores" (
  "symbol" TEXT NOT NULL,
  "timeframe" TEXT NOT NULL,
