-- ── Timescale hypertables / compression / retention ──────────────────────
SELECT create_hypertable('confluence_signals', 'computed_at', chunk_time_interval => INTERVAL '7 days', if_not_exists => TRUE, migrate_data => TRUE);
ALTER TABLE confluence_signals SET (timescaledb.compress, timescaledb.compress_segmentby = 'symbol');
SELECT add_compression_policy('confluence_signals', INTERVAL '30 days', if_not_exists => TRUE);
SELECT add_retention_policy('confluence_signals', INTERVAL '90 days', if_not_exists => TRUE);
SELECT create_hypertable('feature_store', 'date', chunk_time_interval => INTERVAL '90 days', if_not_exists => TRUE, migrate_data => TRUE);
ALTER TABLE feature_store SET (timescaledb.compress, timescaledb.compress_segmentby = 'symbol');
SELECT add_compression_policy('feature_store', INTERVAL '120 days', if_not_exists => TRUE);
SELECT create_hypertable('intraday_ohlcv', 'datetime', chunk_time_interval => INTERVAL '7 days', if_not_exists => TRUE, migrate_data => TRUE);
ALTER TABLE intraday_ohlcv SET (timescaledb.compress, timescaledb.compress_segmentby = 'symbol');
SELECT add_compression_policy('intraday_ohlcv', INTERVAL '30 days', if_not_exists => TRUE);
SELECT add_retention_policy('intraday_ohlcv', INTERVAL '365 days', if_not_exists => TRUE);
SELECT create_hypertable('macro_asset_prices', 'date', chunk_time_interval => INTERVAL '365 days', if_not_exists => TRUE, migrate_data => TRUE);
SELECT create_hypertable('stock_ohlcv', 'date', chunk_time_interval => INTERVAL '90 days', if_not_exists => TRUE, migrate_data => TRUE);
ALTER TABLE stock_ohlcv SET (timescaledb.compress, timescaledb.compress_segmentby = 'symbol');
SELECT add_compression_policy('stock_ohlcv', INTERVAL '180 days', if_not_exists => TRUE);
SELECT create_hypertable('tick_data', 'tick_time', chunk_time_interval => INTERVAL '1 day', if_not_exists => TRUE, migrate_data => TRUE);
ALTER TABLE tick_data SET (timescaledb.compress, timescaledb.compress_segmentby = 'symbol');
SELECT add_compression_policy('tick_data', INTERVAL '7 days', if_not_exists => TRUE);
SELECT add_retention_policy('tick_data', INTERVAL '30 days', if_not_exists => TRUE);
